def clean_language(value: str | None) -> str:
    value = (value or "").split("-", 1)[0].lower()
    return value if value in LANGUAGE_CODES else DEFAULT_LANGUAGE


MOJIBAKE_MARKERS = (
    "Р",
    "СЃ",
    "С‹",
    "СЊ",
    "С‚",
    "Г©",
    "Г±",
    "бѓ",
    "Х",
    "пїЅ",
)


def repair_mojibake(value: str) -> str:
    if not isinstance(value, str) or not value:
        return value
    if not any(marker in value for marker in MOJIBAKE_MARKERS):
        return value
    try:
        repaired = value.encode("cp1251").decode("utf-8")
    except (UnicodeEncodeError, UnicodeDecodeError):
        return value
    return repaired if repaired else value


def localize(values: dict[str, str], language: str | None = None, default: str = "") -> str:
    language = clean_language(language or current_language())
    text = values.get(language) or values.get(DEFAULT_LANGUAGE) or default
    return repair_mojibake(text)


def current_language() -> str:
    return clean_language(get_language())


def translate(key: str, language: str | None = None) -> str:
    language = clean_language(language or current_language())
    values = UI_TEXT.get(key, {})
    return localize(values, language, key.replace("_", " ").title())


def language_options(active: str | None = None) -> list[dict[str, str | bool]]:
    active = clean_language(active or current_language())
    return [
        {
            **item,
            "native": repair_mojibake(str(item["native"])),
            "name": repair_mojibake(str(item["name"])),
            "active": item["code"] == active,
        }
        for item in LANGUAGE_OPTIONS
    ]


