def music_messages(language: str | None = None) -> dict[str, str]:
    language = clean_language(language)
    return {key: values.get(language) or values.get(DEFAULT_LANGUAGE) or key for key, values in MUSIC_TEXT.items()}


def _human_storage(size: int) -> str:
    amount = float(size)
    for unit in ("B", "KB", "MB", "GB", "TB"):
        if amount < 1024 or unit == "TB":
            return f"{amount:.1f} {unit}" if unit != "B" else f"{int(amount)} B"
        amount /= 1024


